def gen(rng):
    def fmt(p, q):
        return (f"{len(p)}\n" + '\n'.join(f"{c} {e}" for c, e in p) + f"\n{len(q)}\n" + '\n'.join(f"{c} {e}" for c, e in q))

    def rc(lim):
        return rng.choice([-1, 1]) * rng.randint(1, lim)

    tests = [fmt([(5, 0)], [(6, 0)]), fmt([(4, 3), (-1, 1)], [(-4, 3), (1, 1)]),
             fmt([(3, 4), (2, 2), (-5, 0)], [(-2, 2), (1, 1), (7, 0)]),
             fmt([(1, 10 ** 9)], [(1, 0)]), fmt([(10 ** 9, 5)], [(10 ** 9, 5)]),
             fmt([(-10 ** 9, 5)], [(-10 ** 9, 5)]), fmt([(2, 3), (1, 2), (1, 1)], [(-1, 1)]),
             fmt([(7, 9)], [(1, 8), (1, 7), (1, 6)])]
    for _ in range(30):
        pe = sorted(rng.sample(range(0, 9), rng.randint(1, 6)), reverse=True)
        qe = sorted(rng.sample(range(0, 9), rng.randint(1, 6)), reverse=True)
        p = [(rc(3), e) for e in pe]
        q = [(rc(3), e) for e in qe]
        tests.append(fmt(p, q))
    N = 50000
    L = 10 ** 9
    pe = sorted(rng.sample(range(L + 1), N), reverse=True)
    qe = sorted(rng.sample(range(L + 1), N), reverse=True)
    tests.append(fmt([(rc(L), e) for e in pe], [(rc(L), e) for e in qe]))
    # half shared exponents: some cancel, some add up past 32-bit range
    shared = pe[::2]
    others = sorted(rng.sample(range(L + 1), N // 2), reverse=True)
    qe2 = sorted(set(shared) | set(others), reverse=True)[:N]
    pc = {e: rc(L) for e in pe}
    qc = {}
    for k, e in enumerate(qe2):
        if e in pc:
            qc[e] = -pc[e] if k % 2 == 0 else pc[e]
        else:
            qc[e] = rc(L)
    tests.append(fmt([(pc[e], e) for e in pe], [(qc[e], e) for e in qe2]))
    tests.append(fmt([(pc[e], e) for e in pe], [(-pc[e], e) for e in pe]))
    tests.append(fmt([(rc(L), e) for e in range(N - 1, -1, -1)], [(rc(L), e) for e in range(2 * N - 1, N - 1, -1)]))
    return tests
